const fs=require('fs'),forge=require('node-forge');
const pub=forge.pki.publicKeyFromPem(fs.readFileSync('samples/keys/partner-root.pub.pem','utf8'));
const sig=forge.util.decode64(fs.readFileSync('samples/sigs/partner-agreement-2019.sig.b64','utf8').trim());
